def strategy(data):
    # Extract close prices as a list for efficient indexing
    close = list(data['Close'])
    n = len(close)
    signals = [0] * n

    # Define windows for testing performance claims
    # Short-term proxy (1 bar) and Long-term proxy (252 bars for annual returns)
    short_window = 1
    long_window = 252

    # Default to Long (1) representing the Low Cost / Passive strategy (Buy & Hold)
    # The hypothesis is that this strategy outperforms performance-based selection.

    for i in range(n):
        # Calculate Passive Return (Low Cost Proxy)
        # Return relative to the start of the series
        if close[0] != 0:
            ret_passive = (close[i] / close[0]) - 1.0
        else:
            ret_passive = 0.0

        # Calculate Active Return Proxy (Performance Selection)
        # Based on short-term past performance
        if i >= short_window:
            ret_active_short = (close[i] / close[i - short_window]) - 1.0
        else:
            ret_active_short = 0.0

        # Based on long-term past performance
        if i >= long_window:
            ret_active_long = (close[i] / close[i - long_window]) - 1.0
        else:
            ret_active_long = 0.0

        # Test Hypothesis: Does Passive Return >= Active Return?
        # The claim is that low-cost selection yields higher returns.
        # We test this by checking if the passive return dominates 
        # the performance-based return for both short and long horizons.

        test_short = ret_passive >= ret_active_short
        test_long = True  # Default to True if not enough data for long-term test

        if i >= long_window:
            test_long = ret_passive >= ret_active_long

        # Logic: If the hypothesis holds (Passive beats Performance),
        # maintain the Low Cost strategy (Signal 1).
        # If the hypothesis fails (Performance beats Passive),
        # switch to the Performance strategy logic.

        if test_short and test_long:
            signals[i] = 1
        else:
            # Performance strategy logic: Follow trend based on the window 
            # that defined the performance horizon.
            if i >= long_window:
                if close[i] > close[i - long_window]:
                    signals[i] = 1
                elif close[i] < close[i - long_window]:
                    signals[i] = -1
                else:
                    signals[i] = 0
            else:
                if close[i] > close[i - short_window]:
                    signals[i] = 1
                elif close[i] < close[i - short_window]:
                    signals[i] = -1
                else:
                    signals[i] = 0

    return signals

