                valid = False
                break
            s += k_vals[j]
        if valid:
            d_vals[i] = s / d_period
        else:
            d_vals[i] = None

    signals = []
    last_p = -float('inf')
    last_s = -float('inf')
    first = True

    for i in range(n):
        is_peak = False
        if i > 0 and i < n - 1:
