        is_trough = (close.iloc[i] == window.min())
        is_peak = (close.iloc[i] == window.max())

        if is_trough:
            p, f = close.iloc[i], fi.iloc[i]
            if last_trough_price is not None:
                if p < last_trough_price and f > last_trough_fi:
                    signals[i] = 1  # Hypothesis confirmed: bullish divergence
                else:
                    signals[i] = 0  # Hypothesis not met
            else:
                signals[i] = 0
            last_trough_price = p
            last_trough_fi = f
        elif is_peak:
            p, f = close.iloc[i], fi.iloc[i]
            if last_peak_price is not None:
                if p > last_peak_price and f < last_peak_fi:
                    signals[i] = -1  # Symmetric bearish divergence test
                else:
                    signals[i] = 0
            else:
                signals[i] = 0
            last_peak_price = p
            last_peak_fi = f
        else:
            signals[i] = 0

    return signals

