    window = 10
    threshold = 2.0
    signals = []

    for i in range(n):
        if i < window - 1:
            signals.append(0)
            continue

        recent = closes[i-window+1 : i+1]
        higher = 0
        lower = 0
        for j in range(1, len(recent)):
            if recent[j] > recent[j-1]:
                higher += 1
            elif recent[j] < recent[j-1]:
                lower += 1

        ratio = (lower / higher) if higher > 0 else 3.0

        # Test hypothesis: if ratio of lower closes to higher closes >= 2:1, 
        # anticipate impending downward move (short position).
        if ratio >= threshold:
            signals.append(-1)
        else:
            signals.append(0)

    return signals

